import React from "react";
import { Link } from "react-router-dom";
import withRouter from "./withRouter";

class Post extends React.Component {

    constructor(props){
        super(props);

        const { id } = this.props.params;

        this.state = {
            post: {},
            comments: [],
            base_URL: "",
            loading: true,
            comment_text: "",
            id: id
        };
    }

    componentDidMount(){

        fetch("http://localhost:8000/api/post/" + this.state.id)
        .then(res => res.json())
        .then(json => {

            this.setState({
                post: json.post,
                comments: json.all_comment.data,
                base_URL: json.base_URL,
                loading: false
            });

        })
        .catch(err=>{
            console.log(err);
            this.setState({loading:false});
        });

    }

    handleCommentChange = (e)=>{
        this.setState({
            comment_text:e.target.value
        });
    }

    render(){

        if(this.state.loading){
            return <p>Loading...</p>
        }


        return(
            <main className="container mt-4 pt-5">
                <div className="container-fluid mt-5">

                    <div className="card mb-4 shadow-sm item-back text-color overflow-hidden rounded-4 boder">

                        <img 
                            src={this.state.base_URL + p.img}
                            alt=""
                            className="post-img rounded-top-4"
                        />

                        <div className="card-body">

                            <h3 className="card-title">{p.title}</h3>

                            <p>{p.display_time}</p>

                            <p className="card-text">{p.description}</p>

                            <div className="d-flex align-items-center mb-3">

                                <img
                                    src={this.state.base_URL + p?.user?.img}
                                    alt=""
                                    className="user-img me-3 rounded-circle boder"
                                />

                                <div>
                                    <Link to={"/profile"} className="text-decoration-none text-color px-2 pt-1 pb-1 mb-2 rounded-3">
                                        {p?.user?.name}
                                    </Link>
                                </div>

                            </div>

                            <div className="d-flex align-items-center gap-2 mb-3">

                                <span>
                                    ❤️
                                </span>

                                <span>{p.like_qty?.length || 0}</span>

                            </div>

                            <form>

                                <div className="mb-3">

                                    <textarea
                                        className="form-control"
                                        rows="2"
                                        placeholder="Write a comment..."
                                        value={this.state.comment_text}
                                        onChange={this.handleCommentChange}
                                    />

                                </div>

                                <button type="button" className="btn btn-theme boder">
                                    Send Comment
                                </button>

                            </form>

                        </div>
                    </div>

                    <div className="shadow-sm item-back p-4 mb-3 boder rounded-4">

                        <h5 className="mb-4">
                            Comments ({this.state.comments.length})
                        </h5>

                        {this.state.comments.map((c,index)=>(
                            
                            <div key={index} className="d-flex mb-3">

                                <img
                                    src={this.state.base_URL + c.img}
                                    alt=""
                                    className="user-img me-3 rounded-circle boder"
                                />

                                <div>

                                    <Link to={"/profile"} className="text-decoration-none text-color px-2 pt-1 pb-1 mb-2 rounded-3">
                                        {c.name}
                                    </Link>

                                    <p className="mb-0">{c.pivot.text}</p>

                                </div>

                            </div>

                        ))}

                    </div>

                </div>
            </main>
        )
    }

}

export default withRouter(Post);
